con:configuration.scriptText:
import se.skl.rivta.tksupport.soapui.ContentAssertions
import se.skl.rivta.tksupport.soapui.ContextHelperTK
def ca = new ContentAssertions(context, messageExchange, log)
def ch = new ContextHelperTK(context, messageExchange, log)

if (ch.getRecordsList())
	ca.assertNoForbiddenValueInAnyRecord('/fc1:engagement/urn1:logicalAddress', "SKLTP-MOCK01")

